import React from 'react';
import { ComponentType, ComponentDef } from '../types';

interface SidebarProps {
  selectedTool: 'SELECT' | 'DELETE';
  onSelectTool: (t: 'SELECT' | 'DELETE') => void;
  onTouchStartItem?: (type: string, e: React.TouchEvent) => void;
  definitions: Record<string, ComponentDef>;
