const Sidebar: React.FC<SidebarProps> = ({ selectedTool, onSelectTool, onTouchStartItem, definitions }) => {

  // Categorize components
  const basicIO = [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.HEX_DISPLAY];
  const gates = [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR];

  const customItems = Object.values(definitions).filter(d => d.type === ComponentType.CUSTOM);

  const handleDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData('application/react-logic-sim', id); // Pass the ID (key) 
    e.dataTransfer.effectAllowed = 'copy';
  };

  const renderGroup = (title: string, items: ComponentDef[], ids: string[]) => (
    <div key={title}>
       <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">{title}</h3>
       <div className="grid grid-cols-2 gap-3">
         {items.map((def, idx) => {
           const id = ids[idx];
           return (
            <div
              key={id}
              draggable={true}
              onDragStart={(e) => handleDragStart(e, id)}
              onTouchStart={(e) => onTouchStartItem && onTouchStartItem(id, e)}
              className="flex flex-col items-center justify-center p-3 rounded border-2 border-slate-100 bg-white hover:border-slate-300 hover:shadow-sm transition-all duration-200 cursor-grab active:cursor-grabbing touch-none"
