              {/* Visual Preview Icon (CSS based) */}
              <div className={`w-8 h-8 mb-2 border border-slate-300 rounded flex items-center justify-center bg-white text-[10px] font-bold text-slate-600 pointer-events-none ${def.type === ComponentType.CUSTOM ? 'bg-slate-50' : ''}`}>
                {def.label.substring(0,3)}
              </div>
              <span className="text-xs font-medium text-slate-700 pointer-events-none truncate w-full text-center">{def.label}</span>
            </div>
           );
         })}
       </div>
    </div>
  );

  return (
    <div className="w-64 bg-white border-r border-slate-200 flex flex-col h-full shadow-lg z-10">
      <div className="p-4 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">LogicFlow</h1>
        <p className="text-xs text-slate-400 mt-1">Simulator v1.3</p>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        {/* Tools */}
        <div>
          <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">Tools</h3>
          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={() => onSelectTool('SELECT')}
              className={`p-2 rounded text-sm font-medium transition-colors ${selectedTool === 'SELECT' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              Cursor
            </button>
            <button
              onClick={() => onSelectTool('DELETE')}
              className={`p-2 rounded text-sm font-medium transition-colors ${selectedTool === 'DELETE' ? 'bg-red-500 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              Delete
            </button>
          </div>
        </div>

        {/* Components */}
        {renderGroup('I/O', basicIO.map(t => definitions[t]), basicIO)}
        {renderGroup('Gates', gates.map(t => definitions[t]), gates)}

        {customItems.length > 0 && (
          <div>
            <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">Your Functions</h3>
            <div className="grid grid-cols-2 gap-3">
              {Object.entries(definitions)
                .filter(([_, def]) => def.type === ComponentType.CUSTOM)
                .map(([id, def]) => (
                  <div
                    key={id}
                    draggable={true}
                    onDragStart={(e) => handleDragStart(e, id)}
                    onTouchStart={(e) => onTouchStartItem && onTouchStartItem(id, e)}
                    className="flex flex-col items-center justify-center p-3 rounded border-2 border-slate-100 bg-slate-50 hover:border-blue-300 hover:shadow-sm transition-all duration-200 cursor-grab active:cursor-grabbing touch-none"
                  >
                     <div className="w-8 h-8 mb-2 border border-slate-300 rounded flex items-center justify-center bg-slate-200 text-[10px] font-bold text-slate-600 pointer-events-none">
