                    </div>
                    <span className="text-xs font-medium text-slate-700 pointer-events-none truncate w-full text-center">{def.label}</span>
                  </div>
              ))}
            </div>
          </div>
        )}

      </div>

      <div className="p-4 bg-slate-50 border-t border-slate-200 text-xs text-slate-500">
        <p>Build a circuit with Input/Output components, then click "Function+" to save it as a chip.</p>
      </div>
    </div>
  );
