import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas from './components/LogicCanvas';
import { ComponentType, ComponentDef } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

const App: React.FC = () => {
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(true); 
  const [tickSpeed, setTickSpeed] = useState(50); 

  // Registry of definitions, starting with defaults
  const [definitions, setDefinitions] = useState<Record<string, ComponentDef>>(COMPONENT_DEFINITIONS);

  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: string, x: number, y: number} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);

  // Function Creation Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFunctionName, setNewFunctionName] = useState("");

  const handleTouchStartItem = (id: string, e: React.TouchEvent) => {
    const touch = e.touches[0];
    setDraggedId(id);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedId) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedId && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;
          setPendingDrop({ type: draggedId, x: relX, y: relY });
        }
      }
      setDraggedId(null);
      setDragPos(null);
    };

    if (draggedId) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedId, dragPos]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  const handleCreateFunction = () => {
    setIsModalOpen(true);
    setNewFunctionName("");
  };

  const saveFunction = () => {
    const canvasEl = canvasWrapperRef.current?.querySelector('div'); // The canvas container
    if (!canvasEl || !(canvasEl as any).getCircuitState) return;

    const { components, wires } = (canvasEl as any).getCircuitState();

    // 1. Identify Inputs and Outputs
    const inputs = components.filter((c: any) => c.type === ComponentType.INPUT_SWITCH);
    const outputs = components.filter((c: any) => c.type === ComponentType.OUTPUT_LED);

    if (inputs.length === 0 && outputs.length === 0) {
      alert("Circuit must have at least one Input Switch or Output LED to be a function.");
      setIsModalOpen(false);
      return;
    }

    // 2. Sort them to have a deterministic order (Top-Bottom, Left-Right)
    const sortFn = (a: any, b: any) => (a.y - b.y) || (a.x - b.x);
    inputs.sort(sortFn);
    outputs.sort(sortFn);

    // 3. Create Definition
    const id = `custom-${Date.now()}`;
    const newDef: ComponentDef = {
      type: ComponentType.CUSTOM,
      label: newFunctionName || `FUNC ${Object.keys(definitions).length - 8}`,
      width: 3, // Fixed width for now
      height: Math.max(inputs.length, outputs.length, 2) + 1, // Dynamic height
      inputs: inputs.length,
      outputs: outputs.length,
      description: "Custom Function",
      customData: {
        internalComponents: components,
        internalWires: wires,
        inputMapping: inputs.map((c: any) => c.id),
        outputMapping: outputs.map((c: any) => c.id)
      }
    };

    // 4. Update State
    setDefinitions(prev => ({ ...prev, [id]: newDef }));
    setIsModalOpen(false);

    // 5. Clear Canvas (Optional, but good for workflow)
    if((canvasEl as any).clearCircuit) {
      (canvasEl as any).clearCircuit();
    }
  };

  return (
    <div className="flex h-screen w-screen bg-slate-50 text-slate-800 font-sans overflow-hidden select-none">

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        onTouchStartItem={handleTouchStartItem}
        definitions={definitions}
      />

      <main className="flex-1 flex flex-col relative">

        {/* Top Toolbar / HUD */}
        <div className="absolute top-4 left-4 right-4 h-12 bg-white/95 backdrop-blur shadow-sm rounded-md flex items-center justify-between px-4 z-10 border border-slate-200 pointer-events-auto">
          <div className="flex items-center space-x-4">
             <div className="flex items-center space-x-2 mr-2">
               <span className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500' : 'bg-slate-300'}`}></span>
               <span className="text-sm font-semibold text-slate-700">{isPlaying ? 'Running' : 'Paused'}</span>
             </div>

             <div className="h-5 w-px bg-slate-200"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-3 py-1 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors"
             >
               {isPlaying ? 'Pause' : 'Resume'}
             </button>

             <button 
                onClick={() => window.location.reload()}
                className="px-3 py-1 text-red-500 hover:text-red-600 rounded text-sm font-medium transition-colors"
              >
                Clear All
              </button>

              <div className="h-5 w-px bg-slate-200"></div>

              <button
                onClick={handleCreateFunction}
                className="px-3 py-1 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-sm font-medium transition-colors shadow-sm flex items-center gap-2"
              >
                <span>Function+</span>
              </button>
          </div>

          <div className="flex items-center space-x-3">
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">DELAY (MS)</span>
            <input 
              type="range" 
              min="5" 
              max="1000" 
              step="5"
              value={tickSpeed} 
              onChange={(e) => setTickSpeed(Number(e.target.value))}
              className="w-32 h-1 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-900" 
            />
            <span className="text-xs text-slate-500 w-8 text-right font-mono">{tickSpeed}ms</span>
          </div>
        </div>

        {/* Main Canvas Area */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            onPendingDropHandled={handlePendingDropHandled}
            definitions={definitions}
          />
        </div>

        {/* Ghost Element for Touch Dragging */}
        {draggedId && dragPos && definitions[draggedId] && (
          <div 
            className="fixed pointer-events-none z-50 opacity-80"
            style={{ 
              left: dragPos.x, 
              top: dragPos.y,
              transform: 'translate(-50%, -50%)'
            }}
          >
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">
                {definitions[draggedId].label}
              </span>
            </div>
          </div>
        )}

      </main>

      {/* New Function Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center">
          <div className="bg-white rounded-lg shadow-xl p-6 w-80">
             <h2 className="text-lg font-bold text-slate-800 mb-4">Create Function Component</h2>
             <p className="text-xs text-slate-500 mb-4">
               Current circuit will be saved as a new component. 
               Input Switches will become inputs, Output LEDs will become outputs.
             </p>
             <label className="block text-xs font-semibold text-slate-700 mb-1">Component Name</label>
             <input 
                type="text" 
                maxLength={6}
                value={newFunctionName}
                onChange={(e) => setNewFunctionName(e.target.value.toUpperCase())}
                placeholder="MYCHIP"
                className="w-full p-2 border border-slate-300 rounded mb-4 text-sm font-mono uppercase focus:border-indigo-500 outline-none"
             />
             <div className="flex justify-end space-x-2">
               <button 
                 onClick={() => setIsModalOpen(false)}
                 className="px-3 py-1.5 text-slate-600 hover:bg-slate-100 rounded text-sm"
               >
                 Cancel
               </button>
               <button 
                 onClick={saveFunction}
                 className="px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-sm font-medium"
               >
                 Create
               </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
